+        ks.setFile("binary.file", value);
+        saveKeystore(ks, password);
+
+        terminal.addSecretInput(password);
+        terminal.setHasOutputStream(true);
+
+        execute("binary.file");
+        assertThat(terminal.getOutputBytes(), equalTo(value));
+    }
